   293→#[derivative(PartialEq, Eq)]
   294→#[ssz(struct_behaviour = "transparent")]
   295→pub struct KzgVerifiedDataColumn<E: EthSpec> {
   296→    data: Arc<DataColumnSidecar<E>>,
   297→}
